<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Edit shift | <?= e(config('app.name')) ?></title><link rel="stylesheet" href="<?= e(app_url('/assets/css/app.css?v=20260713-shift-edit-fix')) ?>">    <link rel="icon" href="<?= e(app_url('/favicon.svg?v=clock-1')) ?>" type="image/svg+xml">
</head>
<body><?php require BASE_PATH . '/app/Views/partials/nav.php'; ?><main class="container narrow">
<div class="page-heading"><div><p class="eyebrow">Scheduling</p><h1>Edit shift</h1></div><a class="back-link" href="<?= e(app_url('/shifts')) ?>">← Back to shifts</a></div>
<?php if ($flash): ?><div class="alert <?= e($flash['type']) ?>"><?= e($flash['message']) ?></div><?php endif; ?>
<section class="panel"><form method="post" action="<?= e(app_url('/shifts/' . $shift['id'] . '/edit')) ?>"><?= csrf_field() ?>
<div class="form-row"><div><label for="code">Code</label><input id="code" name="code" maxlength="40" value="<?= e($old['code'] ?? $shift['code']) ?>" required><?php if (isset($errors['code'])): ?><small class="error"><?= e($errors['code']) ?></small><?php endif; ?></div><div><label for="name">Name</label><input id="name" name="name" maxlength="120" value="<?= e($old['name'] ?? $shift['name']) ?>" required><?php if (isset($errors['name'])): ?><small class="error"><?= e($errors['name']) ?></small><?php endif; ?></div></div>
<div class="form-row"><div><label for="start_time">Start</label><input id="start_time" name="start_time" type="time" value="<?= e($old['start_time'] ?? substr($shift['start_time'],0,5)) ?>" required><?php if (isset($errors['start_time'])): ?><small class="error"><?= e($errors['start_time']) ?></small><?php endif; ?></div><div><label for="end_time">End</label><input id="end_time" name="end_time" type="time" value="<?= e($old['end_time'] ?? substr($shift['end_time'],0,5)) ?>" required><?php if (isset($errors['end_time'])): ?><small class="error"><?= e($errors['end_time']) ?></small><?php endif; ?></div></div>
<div class="form-row three"><div><label for="paid_minutes">Paid minutes</label><input id="paid_minutes" name="paid_minutes" type="number" min="0" max="1440" value="<?= e($old['paid_minutes'] ?? $shift['paid_minutes']) ?>" required><?php if (isset($errors['paid_minutes'])): ?><small class="error"><?= e($errors['paid_minutes']) ?></small><?php endif; ?></div><div><label for="grace_period_minutes">Grace</label><input id="grace_period_minutes" name="grace_period_minutes" type="number" min="0" max="1440" value="<?= e($old['grace_period_minutes'] ?? $shift['grace_period_minutes']) ?>" required><?php if (isset($errors['grace_period_minutes'])): ?><small class="error"><?= e($errors['grace_period_minutes']) ?></small><?php endif; ?></div><div><label for="expected_lunch_minutes">Lunch</label><input id="expected_lunch_minutes" name="expected_lunch_minutes" type="number" min="0" max="1440" value="<?= e($old['expected_lunch_minutes'] ?? $shift['expected_lunch_minutes']) ?>" required><?php if (isset($errors['expected_lunch_minutes'])): ?><small class="error"><?= e($errors['expected_lunch_minutes']) ?></small><?php endif; ?></div></div>
<button type="submit">Save changes</button></form></section></main></body></html>
